import json, sys
sys.path.insert(0, "scripts")
import observe_output as O
def raw(*events):
    return ("\n".join(json.dumps(e) for e in events) + "\n").encode()
def vals(provider, data):
    figures = O.token_figures(provider, data)
    assert tuple(figures) == O.TOKEN_FIGURE_FIELDS, figures
    return {k: figures[k]["value"] for k in O.TOKEN_FIGURE_FIELDS}
assert O.TOKEN_FIGURE_FIELDS == ("input", "output", "reasoning", "cache_read", "cache_write", "total", "without_cache")
c = {"type": "result", "usage": {"input_tokens": 46, "cache_creation_input_tokens": 72207, "cache_read_input_tokens": 1683716, "output_tokens": 15715, "output_tokens_details": {"thinking_tokens": 5122}}}
assert vals("claude", raw(c)) == dict(input=46, output=15715, reasoning=5122, cache_read=1683716, cache_write=72207, total=1771684, without_cache=87968)
x1 = {"type": "turn.completed", "usage": {"input_tokens": 637380, "cached_input_tokens": 605952, "cache_write_input_tokens": 0, "output_tokens": 4791, "reasoning_output_tokens": 1232}}
x2 = {"type": "turn.completed", "usage": {"input_tokens": 517194, "cached_input_tokens": 472832, "cache_write_input_tokens": 0, "output_tokens": 5577, "reasoning_output_tokens": 1089}}
assert vals("codex", raw(x1, x2)) == dict(input=1154574, output=10368, reasoning=2321, cache_read=1078784, cache_write=0, total=1164942, without_cache=86158)
u = {"type": "result", "usage": {"inputTokens": 39280, "outputTokens": 5387, "cacheReadTokens": 233463, "cacheWriteTokens": 0}}
assert vals("cursor", raw(u)) == dict(input=39280, output=5387, reasoning=None, cache_read=233463, cache_write=0, total=278130, without_cache=44667)
assert vals("agent", raw(u))["total"] == 278130
a = {"event": "result", "result": {"status": "SUCCESS", "usage": {"input_tokens": 3216, "output_tokens": 202, "thinking_tokens": 126, "cache_read_tokens": 16873, "total_tokens": 3418}}}
assert vals("agy", raw(a)) == dict(input=3216, output=202, reasoning=126, cache_read=16873, cache_write=None, total=20291, without_cache=3418)
bad_x = json.loads(json.dumps(x1)); bad_x["usage"]["cache_write_input_tokens"] = 5
bad_a = json.loads(json.dumps(a)); bad_a["result"]["usage"]["total_tokens"] = 9999
bad_u = json.loads(json.dumps(u)); del bad_u["usage"]["cacheWriteTokens"]
for provider, event in (("codex", bad_x), ("agy", bad_a), ("cursor", bad_u)):
    v = vals(provider, raw(event))
    assert v["total"] is None and v["without_cache"] is None, (provider, v)
assert all(v is None for v in vals("claude", b"").values())
print("ok")
